import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.function.Consumer;

final class BellBoard {
    private final Map<Class<? extends Fruit>, List<Consumer<Fruit>>> bells = new HashMap<>();

    // Consumer<? super E>: a listener for E or for any supertype of E
    <E extends Fruit> void listen(Class<E> type, Consumer<? super E> listener) {
        bells.computeIfAbsent(type, t -> new ArrayList<>()).add(item -> {
            if (type.isInstance(item)) listener.accept(type.cast(item));   // the adapter
        });
    }

    int ring(Fruit item) {
        List<Consumer<Fruit>> listeners = bells.getOrDefault(item.getClass(), List.of());
        listeners.forEach(l -> l.accept(item));
        return listeners.size();
    }
}

// board.listen(Apple.class, a -> writeSign(a));

