class BellBoard {
    private val bells = HashMap<KClass<out Fruit>, MutableList<(Fruit) -> Unit>>()

    // (E) -> Unit is already Function1<in E, ...>: a listener for any supertype of E fits
    fun <E : Fruit> listen(type: KClass<E>, listener: (E) -> Unit) {
        bells.getOrPut(type) { mutableListOf() }
            .add { item -> type.safeCast(item)?.let(listener) }           // the adapter
    }

    inline fun <reified E : Fruit> listen(noinline listener: (E) -> Unit) = listen(E::class, listener)

    fun ring(item: Fruit): Int {
        val listeners = bells[item::class] ?: return 0
        for (l in listeners) l(item)
        return listeners.size
    }
}

// board.listen<Apple> { writeSign(it) }

steps.code:
fun parseDelivery(note: Map<*, *>): Either<String, Fruit> {
    val name = note["name"] as? String ?: return Either.Left("missing name")
    val grams = (note["grams"] as? Number)?.toInt() ?: return Either.Left("missing weight")
    return when (note["kind"]) {
        "apple" -> Either.Right(Apple(name, grams))
        "lemon" -> Either.Right(Lemon(name, grams))
        else -> Either.Left("unknown kind ${note["kind"]}")
